(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const inp = $('#inp');
  const outWord = $('#outWord');
  const outMeta = $('#outMeta');
  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const btnClear = $('#btnClear');
  const btnAcute = $('#btnAcute');
  const btnGrave = $('#btnGrave');
  const btnStrip = $('#btnStrip');
  const chips = $('#chips');

  const examples = [
    'βουπληξ','κωμοπληξ','κυματοπληξ','μεθυπληξ','οιστροπληξ','παραπληξ','λαοπληξ','ακανθοπληξ',
    'υσπληξ','αντιπηξ','χηναλωπηξ',
    'αρρωξ','απορρωξ','κυαμοτρωξ','γραμματοτρωξ','θυλακοτρωξ','απτωξ','πολυπτωξ','κυμορρωξ',
    'θηροδιωξ','αιγοδιωξ',
    'γυναιξ','απαις','καγυναιξ',
    'μακαρ','δαμαρ'
  ];

  // Combining marks
  const ACUTE = '\u0301';
  const GRAVE = '\u0300';
  const CIRC  = '\u0342';

  const greekVowels = new Set([
    'α','ε','η','ι','ο','υ','ω',
    'Α','Ε','Η','Ι','Ο','Υ','Ω',
    'ά','έ','ή','ί','ό','ύ','ώ','Ά','Έ','Ή','Ί','Ό','Ύ','Ώ',
    'ὰ','ὲ','ὴ','ὶ','ὸ','ὺ','ὼ','Ὰ','Ὲ','Ὴ','Ὶ','Ὸ','Ὺ','Ὼ',
    'ᾶ','ῆ','ῖ','ῦ','ῶ','ᾷ','ῇ','ῷ',
    'αι','ει','οι','υι','αυ','ευ','ου','ηυ'
  ]);

  function normalizeGreek(s){
    return (s||'').trim();
  }

  function stripCombining(s){
    // Remove common combining diacritics (accents, breathings, iota subscript, diaeresis)
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function lastVowelIndexNFD(s){
    // Work in NFD so combining marks are separate.
    const nfd = s.normalize('NFD');
    // Find last base vowel letter (Greek) in the string.
    const baseVowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
    for(let i=nfd.length-1;i>=0;i--){
      const ch = nfd[i];
      if(baseVowels.has(ch)) return { nfd, i };
    }
    return { nfd, i: -1 };
  }

  function removeAccentMarksNFD(nfd){
    return nfd.replace(new RegExp('['+ACUTE+GRAVE+CIRC+']','g'), '');
  }

  function applyFinalAccent(word, which){
    const clean = stripCombining(word);
    const { nfd, i } = lastVowelIndexNFD(clean);
    if(i<0) return clean;
    let nfd2 = removeAccentMarksNFD(nfd);
    const mark = which === 'acute' ? ACUTE : which === 'grave' ? GRAVE : '';
    if(!mark) return nfd2.normalize('NFC');
    nfd2 = nfd2.slice(0, i+1) + mark + nfd2.slice(i+1);
    return nfd2.normalize('NFC');
  }

  function endsWithAny(s, arr){
    return arr.some(x => s.endsWith(x));
  }

  function guessRule(raw){
    const original = normalizeGreek(raw);
    const bare = stripCombining(original).toLowerCase();

    // Heuristic buckets inspired by the passage
    if(endsWithAny(bare, ['διωξ'])){
      return { ending: '-δίωξ', suggestion: 'grave', why: 'Herodian: θηροδίωξ / αἰγοδίωξ are βαρυτονά (two syllables kept in the compound).', confidence: 'high' };
    }
    if(endsWithAny(bare, ['ωξ'])){
      return { ending: '-ωξ', suggestion: 'acute', why: 'Herodian: -ωξ compounds tend to be final-acute when the compound ends with a single syllable.', confidence: 'medium' };
    }
    if(endsWithAny(bare, ['αιξ'])){
      // Special-case γυναιξ / -γυναιξ
      if(bare === 'γυναιξ' || bare.endsWith('γυναιξ')){
        return { ending: '-αιξ (γύναιξ)', suggestion: 'grave', why: 'Herodian: γύναιξ is special; in compounds it appears and is βαρυτονόν.', confidence: 'high' };
      }
      return { ending: '-αιξ', suggestion: 'grave', why: 'Passage focuses on -αιξ gender/analogy; toy defaults to final-grave for play.', confidence: 'low' };
    }
    if(endsWithAny(bare, ['αρ'])){
      // crude: if more than one syllable-ish (length > 3)
      const conf = bare.length >= 4 ? 'medium' : 'low';
      return { ending: '-αρ', suggestion: 'grave', why: 'Herodian: -αρ (more than one syllable) is βαρυτονόν (e.g. μάκαρ, δάμαρ).', confidence: conf };
    }
    if(endsWithAny(bare, ['ηξ','πηξ','ληξ','τηξ'])){
      // non-adjectival exceptions mentioned
      if(bare === 'υσπληξ' || bare === 'αντιπηξ' || bare.endsWith('λωπηξ')){
        return { ending: '-ηξ (exception)', suggestion: 'grave', why: 'Herodian: ὕσπληξ, ἀντίπηξ, χηναλώπηξ are βαρυτονά (not adjectival / analogies).', confidence: 'high' };
      }
      return { ending: '-ηξ', suggestion: 'acute', why: 'Herodian: adjectival verb-based compounds in -ηξ are final-acute (e.g. βουπλήξ).', confidence: 'medium' };
    }

    return { ending: '—', suggestion: 'acute', why: 'No matching ending detected; toy will just accent the last vowel.', confidence: 'low' };
  }

  function badge(conf){
    const cls = conf === 'high' ? 'good' : conf === 'medium' ? 'warn' : 'bad';
    const label = conf === 'high' ? 'high' : conf === 'medium' ? 'medium' : 'low';
    return `<span class="badge ${cls}">confidence: ${label}</span>`;
  }

  function render(){
    const raw = normalizeGreek(inp.value);
    if(!raw){
      outWord.textContent = '—';
      outMeta.textContent = 'Enter a word to see a rule guess.';
      return;
    }
    const g = guessRule(raw);
    const suggested = applyFinalAccent(raw, g.suggestion);
    outWord.textContent = suggested;
    outMeta.innerHTML = `<div><b>Detected:</b> ${escapeHtml(g.ending)} · <b>Suggested:</b> final-${g.suggestion === 'acute' ? 'acute (ὀξύνεται)' : 'grave (βαρύνεται)'} ${badge(g.confidence)}</div>`+
                        `<div style="margin-top:6px">${escapeHtml(g.why)}</div>`;
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function loadExample(w){
    inp.value = w;
    render();
    inp.focus();
    inp.setSelectionRange(inp.value.length, inp.value.length);
  }

  // Chips
  const uniq = Array.from(new Set(examples));
  uniq.slice(0, 28).forEach(w => {
    const d = document.createElement('div');
    d.className = 'chip';
    d.textContent = w;
    d.addEventListener('click', () => loadExample(w));
    chips.appendChild(d);
  });

  btnAnalyze.addEventListener('click', render);
  inp.addEventListener('input', () => {
    // live update, but lightweight
    render();
  });

  btnRandom.addEventListener('click', () => {
    const w = uniq[Math.floor(Math.random()*uniq.length)];
    loadExample(w);
  });

  btnClear.addEventListener('click', () => {
    inp.value = '';
    render();
    inp.focus();
  });

  btnAcute.addEventListener('click', () => {
    const raw = normalizeGreek(inp.value);
    if(!raw) return;
    const w = applyFinalAccent(raw, 'acute');
    inp.value = w;
    render();
  });

  btnGrave.addEventListener('click', () => {
    const raw = normalizeGreek(inp.value);
    if(!raw) return;
    const w = applyFinalAccent(raw, 'grave');
    inp.value = w;
    render();
  });

  btnStrip.addEventListener('click', () => {
    const raw = normalizeGreek(inp.value);
    if(!raw) return;
    inp.value = stripCombining(raw);
    render();
  });

  // Seed
  loadExample('βουπληξ');
})();

